I will update the application to implement the Admin Leaderboard functionality. This involves creating a new view component for the admin to see the leaderboard, updating the global state to support this new view, and linking it in the Admin Dashboard.

# Updated files:

## context/AppContext.tsx

Updated the `AdminView` type definition to include `'leaderboard_overview'`.

```tsx
<change>
    <file>context/AppContext.tsx</file>
    <description>Add 'leaderboard_overview' to AdminView type definition</description>
    <content><![CDATA[import React, { createContext, useContext, useReducer, useEffect, ReactNode } from 'react';
import { User, Puzzle, Achievement } from '../lib/types';
import * as Auth from '../lib/auth';
import * as PuzzleService from '../lib/puzzleService';
import { achievements as achievementData } from '../data/achievements';

type View = 'login' | 'admin_dashboard' | 'player_dashboard' | 'puzzles' | 'leaderboard' | 'profile' | 'puzzle_view';
type AdminView = 'main' | 'puzzle_management' | 'category_management' | 'player_management' | 'leaderboard_overview';
type ToastMessage = { id: number; message: string; type: 'success' | 'error' };

interface AppState {
    user: User | null;
    view: View;
    adminView: AdminView;
    selectedCategory: string | null;
    currentPuzzle: Puzzle | null;
    puzzles: Record<string, Puzzle[]>;
    achievements: Achievement[];
    players: User[];
    toasts: ToastMessage[];
}

type Action =
    | { type: 'INITIALIZE_DATA'; payload: { puzzles: Record<string, Puzzle[]>, players: User[] } }
    | { type: 'LOGIN_SUCCESS'; payload: User }
    | { type: 'LOGOUT' }
    | { type: 'SET_VIEW'; payload: View }
    | { type: 'SET_ADMIN_VIEW', payload: AdminView }
    | { type: 'SELECT_CATEGORY'; payload: string | null }
    | { type: 'START_PUZZLE'; payload: Puzzle }
    | { type: 'COMPLETE_PUZZLE'; payload: { puzzleId: string; points: number } }
    | { type: 'ADD_PUZZLE'; payload: Puzzle }
    | { type: 'EDIT_PUZZLE'; payload: Puzzle }
    | { type: 'DELETE_PUZZLE'; payload: string }
    | { type: 'ADD_CATEGORY', payload: string }
    | { type: 'EDIT_CATEGORY', payload: { oldName: string; newName: string } }
    | { type: 'DELETE_CATEGORY', payload: string }
    | { type: 'ADD_TOAST'; payload: { message: string; type: 'success' | 'error' } }
    | { type: 'REMOVE_TOAST'; payload: number };

const initialState: AppState = {
    user: null,
    view: 'player_dashboard',
    adminView: 'main',
    selectedCategory: null,
    currentPuzzle: null,
    puzzles: {},
    achievements: achievementData,
    players: [],
    toasts: [],
};

const AppContext = createContext<{
    state: AppState;
    dispatch: React.Dispatch<Action>;
    login: typeof Auth.login;
    signup: typeof Auth.signup;
    logout: () => void;
    selectCategory: (category: string | null) => void;
    addToast: (message: string, type?: 'success' | 'error') => void;
    addPuzzle: (puzzle: Puzzle) => void;
    editPuzzle: (puzzle: Puzzle) => void;
    deletePuzzle: (puzzleId: string) => void;
    addCategory: (name: string) => void;
    editCategory: (oldName: string, newName: string) => void;
    deleteCategory: (name: string) => void;
}>({
    state: initialState,
    dispatch: () => null,
    login: Auth.login,
    signup: Auth.signup,
    logout: () => {},
    selectCategory: () => {},
    addToast: () => {},
    addPuzzle: () => {},
    editPuzzle: () => {},
    deletePuzzle: () => {},
    addCategory: () => {},
    editCategory: () => {},
    deleteCategory: () => {},
});

const appReducer = (state: AppState, action: Action): AppState => {
    switch (action.type) {
        case 'INITIALIZE_DATA':
            return {
                ...state,
                puzzles: action.payload.puzzles,
                players: action.payload.players,
            };
        case 'LOGIN_SUCCESS':
            return {
                ...state,
                user: action.payload,
                view: action.payload.role === 'admin' ? 'admin_dashboard' : 'player_dashboard',
                adminView: 'main',
                players: Auth.getPlayers(),
            };
        case 'LOGOUT':
            return {
                ...initialState,
                user: null,
                view: 'login',
                puzzles: PuzzleService.getPuzzles(),
                players: Auth.getPlayers(),
            };
        case 'SET_VIEW':
            return {
                ...state,
                view: action.payload,
            };
        case 'SET_ADMIN_VIEW':
             if (state.user?.role !== 'admin') return state;
            return {
                ...state,
                adminView: action.payload,
            };
        case 'SELECT_CATEGORY':
            return {
                ...state,
                selectedCategory: action.payload,
            };
        case 'START_PUZZLE':
            return {
                ...state,
                currentPuzzle: action.payload,
                view: 'puzzle_view',
            };
        case 'COMPLETE_PUZZLE': {
            if (!state.user || state.user.solvedPuzzleIds.includes(action.payload.puzzleId)) {
                return state; // Do not award points if puzzle is already solved
            }

            const totalXp = state.user.xp + (state.user.level * state.user.xpToNextLevel) + action.payload.points;

            const updatedUser = {
                ...state.user,
                points: state.user.points + action.payload.points,
                xp: totalXp, // We pass total XP to updateUser which will calculate the new level state
                solvedPuzzleIds: [...state.user.solvedPuzzleIds, action.payload.puzzleId],
            };

            Auth.updateUser(updatedUser);
            // After updating, get the fresh user data back
            const freshUser = Auth.getLoggedInUser();

            return {
                ...state,
                user: freshUser, // Use the fresh user data with new level info
                players: Auth.getPlayers(),
            };
        }
        case 'ADD_PUZZLE': {
             if (state.user?.role !== 'admin') return state;
             const newPuzzles = PuzzleService.addPuzzle(action.payload);
             return {
                 ...state,
                 puzzles: newPuzzles,
             };
        }
        case 'EDIT_PUZZLE': {
            if (state.user?.role !== 'admin') return state;
            const newPuzzles = PuzzleService.editPuzzle(action.payload);
            return { ...state, puzzles: newPuzzles };
        }
        case 'DELETE_PUZZLE': {
            if (state.user?.role !== 'admin') return state;
            const newPuzzles = PuzzleService.deletePuzzle(action.payload);
            return { ...state, puzzles: newPuzzles };
        }
        case 'ADD_CATEGORY': {
            if (state.user?.role !== 'admin') return state;
            const newPuzzles = PuzzleService.addCategory(action.payload);
            return { ...state, puzzles: newPuzzles };
        }
        case 'EDIT_CATEGORY': {
            if (state.user?.role !== 'admin') return state;
            const newPuzzles = PuzzleService.editCategory(action.payload.oldName, action.payload.newName);
            return { ...state, puzzles: newPuzzles };
        }
        case 'DELETE_CATEGORY': {
            if (state.user?.role !== 'admin') return state;
            const newPuzzles = PuzzleService.deleteCategory(action.payload);
            return { ...state, puzzles: newPuzzles };
        }
        case 'ADD_TOAST':
            return {
                ...state,
                toasts: [...state.toasts, { ...action.payload, id: Date.now() }],
            };
        case 'REMOVE_TOAST':
            return {
                ...state,
                toasts: state.toasts.filter(toast => toast.id !== action.payload),
            };
        default:
            return state;
    }
};

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [state, dispatch] = useReducer(appReducer, initialState);

    useEffect(() => {
        const puzzles = PuzzleService.getPuzzles();
        const players = Auth.getPlayers();
        dispatch({ type: 'INITIALIZE_DATA', payload: { puzzles, players } });

        const loggedInUser = Auth.getLoggedInUser();
        if (loggedInUser) {
            dispatch({ type: 'LOGIN_SUCCESS', payload: loggedInUser });
        }
    }, []);

    const logout = () => {
        Auth.logout();
        dispatch({ type: 'LOGOUT' });
        addToast('You have been logged out.');
    };

    const addToast = (message: string, type: 'success' | 'error' = 'success') => {
        dispatch({ type: 'ADD_TOAST', payload: { message, type } });
    };

    const selectCategory = (category: string | null) => {
        dispatch({ type: 'SELECT_CATEGORY', payload: category });
    };

    const addPuzzle = (puzzle: Puzzle) => dispatch({ type: 'ADD_PUZZLE', payload: puzzle });
    const editPuzzle = (puzzle: Puzzle) => dispatch({ type: 'EDIT_PUZZLE', payload: puzzle });
    const deletePuzzle = (puzzleId: string) => dispatch({ type: 'DELETE_PUZZLE', payload: puzzleId });
    const addCategory = (name: string) => dispatch({ type: 'ADD_CATEGORY', payload: name });
    const editCategory = (oldName: string, newName: string) => dispatch({ type: 'EDIT_CATEGORY', payload: { oldName, newName } });
    const deleteCategory = (name: string) => dispatch({ type: 'DELETE_CATEGORY', payload: name });

    return (
        <AppContext.Provider value={{ state, dispatch, login: Auth.login, signup: Auth.signup, logout, selectCategory, addToast, addPuzzle, editPuzzle, deletePuzzle, addCategory, editCategory, deleteCategory }}>
            {children}
        </AppContext.Provider>
    );
};

export const useAppContext = () => useContext(AppContext);]]></content>
</change>
```

## components/AdminDashboard.tsx

Connected the new view to the dashboard buttons and logic.

```tsx
<change>
    <file>components/AdminDashboard.tsx</file>
    <description>Add AdminLeaderboard view handling</description>
    <content><![CDATA[import React from 'react';
import PuzzleIcon from './icons/PuzzleIcon';
import UserCircleIcon from './icons/UserCircleIcon';
import ChartBarIcon from './icons/ChartBarIcon';
import LogoutIcon from './icons/LogoutIcon';
import { useAppContext } from '../context/AppContext';
import PuzzleManagement from './admin/PuzzleManagement';
import CategoryManagement from './admin/CategoryManagement';
import PlayerManagement from './admin/PlayerManagement';
import AdminLeaderboard from './admin/AdminLeaderboard';
import { motion } from 'framer-motion';

const AdminDashboard: React.FC = () => {
    const { state, logout, dispatch } = useAppContext();
    const { user, adminView } = state;

    // Gracefully handle the exit transition where user might be null
    if (!user) {
        return <div className="min-h-screen bg-slate-900"></div>;
    }

    const setAdminView = (view: 'main' | 'puzzle_management' | 'category_management' | 'player_management' | 'leaderboard_overview') => {
        dispatch({ type: 'SET_ADMIN_VIEW', payload: view });
    };

    if (adminView === 'puzzle_management') return <PuzzleManagement />;
    if (adminView === 'category_management') return <CategoryManagement />;
    if (adminView === 'player_management') return <PlayerManagement />;
    if (adminView === 'leaderboard_overview') return <AdminLeaderboard />;

    return (
        <div className="min-h-screen bg-slate-900 text-white p-4 sm:p-6 lg:p-8">
            <header className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold text-slate-100">Admin Dashboard</h1>
                    <p className="text-slate-400">Logged in as: {user.email}</p>
                </div>
                <motion.button
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    onClick={logout}
                    className="flex items-center gap-2 px-4 py-2 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-800 focus:ring-red-500 transition-all duration-300"
                >
                    <LogoutIcon className="w-5 h-5" />
                    <span>Log Out</span>
                </motion.button>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="bg-slate-800/50 backdrop-blur-md rounded-xl p-6 border border-slate-700 hover:border-sky-500 transition-colors duration-300">
                    <div className="flex items-center gap-4 mb-4">
                        <PuzzleIcon className="w-8 h-8 text-sky-400" />
                        <h2 className="text-xl font-semibold text-slate-100">Puzzle Management</h2>
                    </div>
                    <p className="text-slate-400 mb-4">
                        Create, edit, and delete code puzzles. Organize them into categories and set difficulty levels.
                    </p>
                    <button 
                        onClick={() => setAdminView('puzzle_management')}
                        className="w-full bg-sky-600 hover:bg-sky-700 text-white font-bold py-2 px-4 rounded-lg transition-colors">
                        Manage Puzzles
                    </button>
                </div>

                <div className="bg-slate-800/50 backdrop-blur-md rounded-xl p-6 border border-slate-700 hover:border-purple-500 transition-colors duration-300">
                    <div className="flex items-center gap-4 mb-4">
                        <svg xmlns="http://www.w3.org/2000/svg" className="w-8 h-8 text-purple-400" viewBox="0 0 20 20" fill="currentColor">
                          <path d="M2 6a2 2 0 012-2h5l2 2h5a2 2 0 012 2v6a2 2 0 01-2 2H4a2 2 0 01-2-2V6z" />
                        </svg>
                        <h2 className="text-xl font-semibold text-slate-100">Category Management</h2>
                    </div>
                    <p className="text-slate-400 mb-4">
                        Create, rename, and delete the categories used to group puzzles for players.
                    </p>
                    <button 
                        onClick={() => setAdminView('category_management')}
                        className="w-full bg-purple-600 hover:bg-purple-700 text-white font-bold py-2 px-4 rounded-lg transition-colors">
                        Manage Categories
                    </button>
                </div>

                <div className="bg-slate-800/50 backdrop-blur-md rounded-xl p-6 border border-slate-700 hover:border-green-500 transition-colors duration-300">
                    <div className="flex items-center gap-4 mb-4">
                        <UserCircleIcon className="w-8 h-8 text-green-400" />
                        <h2 className="text-xl font-semibold text-slate-100">Player Management</h2>
                    </div>
                    <p className="text-slate-400 mb-4">
                        View player progress, achievements, and statistics. Monitor overall engagement.
                    </p>
                    <button onClick={() => setAdminView('player_management')} className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-2 px-4 rounded-lg transition-colors">
                        View Players
                    </button>
                </div>

                <div className="bg-slate-800/50 backdrop-blur-md rounded-xl p-6 border border-slate-700 hover:border-yellow-500 transition-colors duration-300">
                    <div className="flex items-center gap-4 mb-4">
                        <ChartBarIcon className="w-8 h-8 text-yellow-400" />
                        <h2 className="text-xl font-semibold text-slate-100">Leaderboard Overview</h2>
                    </div>
                    <p className="text-slate-400 mb-4">
                        Observe the current rankings and point distribution across all players on the platform.
                    </p>
                    <button onClick={() => setAdminView('leaderboard_overview')} className="w-full bg-yellow-600 hover:bg-yellow-700 text-white font-bold py-2 px-4 rounded-lg transition-colors">
                        See Leaderboard
                    </button>
                </div>
            </div>
        </div>
    );
};

export default AdminDashboard;]]></content>
</change>
```

## components/admin/AdminLeaderboard.tsx

Created the new Admin Leaderboard component.

```tsx
<change>
    <file>components/admin/AdminLeaderboard.tsx</file>
    <description>Create AdminLeaderboard component</description>
    <content><![CDATA[import React from 'react';
import { useAppContext } from '../../context/AppContext';
import TrophyIcon from '../icons/TrophyIcon';

const getRankColor = (rank: number) => {
    switch (rank) {
        case 1: return 'text-yellow-400';
        case 2: return 'text-gray-300';
        case 3: return 'text-yellow-600';
        default: return 'text-gray-400';
    }
};

const AdminLeaderboard: React.FC = () => {
    const { state, dispatch } = useAppContext();
    const { players } = state;

    const sortedPlayers = [...players]
        .filter(p => p.role === 'player')
        .sort((a, b) => b.points - a.points);

    return (
        <div className="min-h-screen bg-gradient-to-b from-gray-900 to-slate-900 text-white p-4 sm:p-6 lg:p-8 fade-in">
             <header className="flex items-center mb-8">
                <button onClick={() => dispatch({ type: 'SET_ADMIN_VIEW', payload: 'main' })} className="mr-4 text-blue-400 hover:text-blue-300 transition-colors">
                    &larr; Back
                </button>
                <h1 className="text-3xl font-bold text-gray-100">Global Leaderboard</h1>
            </header>

            <div className="bg-slate-800/50 backdrop-blur-md rounded-xl border border-slate-700 shadow-2xl overflow-hidden">
                 <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-800 text-slate-400 text-sm uppercase">
                        <tr>
                            <th className="p-4">Rank</th>
                            <th className="p-4">Player</th>
                            <th className="p-4 text-center">Level</th>
                            <th className="p-4 text-right">Points</th>
                            <th className="p-4 text-center">Puzzles Solved</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-700">
                        {sortedPlayers.length > 0 ? (
                            sortedPlayers.map((player, index) => {
                                const rank = index + 1;
                                return (
                                    <tr key={player.id} className="hover:bg-slate-800/50 transition-colors">
                                        <td className="p-4">
                                            <div className="flex items-center gap-2">
                                                <span className={`font-bold text-lg w-6 text-center ${getRankColor(rank)}`}>{rank}</span>
                                                {rank <= 3 && <TrophyIcon className={`w-5 h-5 ${getRankColor(rank)}`} />}
                                            </div>
                                        </td>
                                        <td className="p-4 font-medium text-slate-200">
                                            {player.email}
                                        </td>
                                         <td className="p-4 text-center text-slate-400">
                                            {player.level}
                                        </td>
                                        <td className="p-4 text-right font-mono text-blue-400 font-bold">
                                            {player.points.toLocaleString()}
                                        </td>
                                        <td className="p-4 text-center text-slate-400">
                                            {player.solvedPuzzleIds.length}
                                        </td>
                                    </tr>
                                );
                            })
                        ) : (
                            <tr>
                                <td colSpan={5} className="p-8 text-center text-slate-500">
                                    No players found.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default AdminLeaderboard;]]></content>
</change>

