### App.tsx
```tsx
import React from 'react';
import { AnimatePresence, motion, Transition } from 'framer-motion';
import { useAppContext } from './context/AppContext';

import LoginPage from './components/LoginPage';
import AdminDashboard from './components/AdminDashboard';
import PlayerLayout from './components/PlayerLayout';
import ToastContainer from './components/ToastContainer';

const pageVariants = {
    initial: { opacity: 0, y: 20 },
    in: { opacity: 1, y: 0 },
    out: { opacity: 0, y: -20 },
};

const pageTransition: Transition = {
    type: 'tween',
    ease: 'anticipate',
    duration: 0.5,
};

const App: React.FC = () => {
    const { state } = useAppContext();
    const { user } = state;

    return (
        <div className="min-h-screen w-full bg-slate-900">
            <AnimatePresence mode="wait">
                {!user ? (
                    <motion.div
                        key="login"
                        initial="initial"
                        animate="in"
                        exit="out"
                        variants={pageVariants}
                        transition={pageTransition}
                        className="w-full"
                    >
                        <LoginPage />
                    </motion.div>
                ) : user.role === 'admin' ? (
                    <motion.div
                        key="admin"
                        initial="initial"
                        animate="in"
                        exit="out"
                        variants={pageVariants}
                        transition={pageTransition}
                        className="w-full"
                    >
                        <AdminDashboard />
                    </motion.div>
                ) : (
                    <motion.div
                        key="player"
                        initial="initial"
                        animate="in"
                        exit="out"
                        variants={pageVariants}
                        transition={pageTransition}
                        className="w-full"
                    >
                        <PlayerLayout />
                    </motion.div>
                )}
            </AnimatePresence>
            <ToastContainer />
        </div>
    );
};

export default App;
```

## 2. Core Logic & State Management

### lib/types.ts
```ts
export interface Puzzle {
    id: string;
    title: string;
    difficulty: 'Easy' | 'Medium' | 'Hard';
    points: number;
    description: string;
    code: string;
    answer: string;
    category: string;
}

export interface Achievement {
    id: string;
    name: string;
    description: string;
    icon: string;
}

export interface User {
    id: number;
    email: string;
    password: string;
    role: 'player' | 'admin';
    points: number;
    xp: number;
    level: number;
    xpToNextLevel: number;
    solvedPuzzleIds: string[];
    achievements: string[];
}
```

