                        const puzzleCount = puzzles[category]?.length || 0;
                        const solvedCount = puzzles[category]?.filter(p => user?.solvedPuzzleIds.includes(p.id)).length || 0;
                        const progress = puzzleCount > 0 ? (solvedCount / puzzleCount) * 100 : 0;

                        return (
                            <motion.div 
                                key={category} 
                                variants={itemVariants}
                                whileHover={{ scale: 1.03 }}
                                whileTap={{ scale: 0.98 }}
                                onClick={() => selectCategory(category)}
                                className="bg-slate-800/50 backdrop-blur-md rounded-2xl p-8 border border-slate-700 cursor-pointer hover:border-sky-500 hover:shadow-lg hover:shadow-sky-500/10 transition-all duration-300 group"
                            >
                                <div className="flex items-center justify-between mb-6">
                                    <div className="p-3 bg-slate-900 rounded-xl group-hover:bg-sky-500/20 transition-colors">
                                        {getCategoryIcon(category)}
                                    </div>
                                    <span className="bg-slate-700 text-slate-300 text-xs font-bold px-3 py-1 rounded-full">
                                        {puzzleCount} Puzzles
