                                </div>
                                <p className="text-xs text-right text-slate-400">{solvedCount} / {puzzleCount} Solved</p>
                            </motion.div>
                        );
                    }) : (
                        <div className="col-span-full text-center text-slate-500 py-10">
                            No categories available. Please check back later.
                        </div>
                    )}
                </motion.div>
            </div>
        );
    }

    return (
        <div className="container mx-auto">
            <button 
                onClick={() => selectCategory(null)}
                className="flex items-center gap-2 text-sky-400 hover:text-sky-300 mb-6 transition-colors font-semibold group"
            >
                <span className="group-hover:-translate-x-1 transition-transform">&larr;</span> Back to Categories
            </button>

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
                <h1 className="text-3xl font-bold text-slate-100">{selectedCategory}</h1>
            </div>

            <div className="flex flex-col md:flex-row gap-4 mb-8 bg-slate-900/50 p-4 rounded-xl border border-slate-800">
                <div className="relative w-full md:w-1/2">
                    <input
                        type="text"
                        placeholder="Search puzzles..."
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 bg-slate-800 border border-slate-700 rounded-lg text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-sky-500"
                    />
                    <svg className="w-5 h-5 text-slate-400 absolute left-3 top-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                </div>
                <div className="flex items-center gap-2 w-full md:w-auto overflow-x-auto pb-2 md:pb-0">
