import React from 'react';
import { AnimatePresence, motion, Transition } from 'framer-motion';
import Navbar from './Navbar';
import PlayerDashboard from './PlayerDashboard';
import PuzzleList from './PuzzleList';
import Leaderboard from './Leaderboard';
import Profile from './Profile';
import PuzzleView from './PuzzleView';
import { useAppContext } from '../context/AppContext';

const pageVariants = {
    initial: { opacity: 0, scale: 0.98 },
    in: { opacity: 1, scale: 1 },
    out: { opacity: 0, scale: 0.98 },
};

const pageTransition: Transition = {
    type: 'tween',
    ease: 'easeOut',
    duration: 0.3,
};

const PlayerLayout: React.FC = () => {
    const { state, logout, dispatch, selectCategory } = useAppContext();
    const { view, currentPuzzle, user } = state;

    // Graceful handling for exit animation when user becomes null during logout
    if (!user) {
        return (
            <div className="flex flex-col min-h-screen bg-slate-900 text-white">
                <div className="h-16 border-b border-slate-800 bg-slate-900/70 backdrop-blur-lg"></div>
                <main className="flex-grow p-4 sm:p-6 lg:p-8"></main>
            </div>
        );
    }

    const setView = (v: any) => dispatch({ type: 'SET_VIEW', payload: v });

    const renderView = () => {
        switch(view) {
            case 'player_dashboard': return <PlayerDashboard />;
            case 'puzzles': return <PuzzleList />;
            case 'leaderboard': return <Leaderboard />;
            case 'profile': return <Profile />;
            case 'puzzle_view': return currentPuzzle ? <PuzzleView puzzle={currentPuzzle} /> : <PuzzleList />;
            default: return <PlayerDashboard />;
        }
    };

    return (
        <div className="flex flex-col min-h-screen bg-slate-900 text-white">
