                userEmail={user.email} 
                onLogout={logout} 
                setView={setView} 
                selectCategory={selectCategory}
                activeView={view} 
            />
            <main className="flex-grow p-4 sm:p-6 lg:p-8">
                <AnimatePresence mode="wait">
                    <motion.div
                        key={view}
                        initial="initial"
                        animate="in"
                        exit="out"
                        variants={pageVariants}
                        transition={pageTransition}
                    >
                        {renderView()}
                    </motion.div>
                </AnimatePresence>
            </main>
        </div>
    );
};

export default PlayerLayout;
