```tsx
import React, { useState, useMemo } from 'react';
import { motion, Variants } from 'framer-motion';
import { Puzzle } from '../lib/types';
import { useAppContext } from '../context/AppContext';
import PuzzleIcon from './icons/PuzzleIcon';

const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
        opacity: 1,
        transition: {
            staggerChildren: 0.05,
        },
    },
};

const itemVariants: Variants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
        y: 0,
        opacity: 1,
        transition: { type: 'spring', stiffness: 100 },
    },
};

// Helper to generate an icon/visual based on category name
const getCategoryIcon = (categoryName: string) => {
    const name = categoryName.toLowerCase();
    if (name.includes('array')) return (
        <svg xmlns="http://www.w3.org/2000/svg" className="w-10 h-10 text-purple-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"></rect><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path></svg>
    );
    if (name.includes('async') || name.includes('promise')) return (
        <svg xmlns="http://www.w3.org/2000/svg" className="w-10 h-10 text-yellow-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"></polygon></svg>
    );
    if (name.includes('object') || name.includes('class')) return (
        <svg xmlns="http://www.w3.org/2000/svg" className="w-10 h-10 text-blue-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg>
    );
    // Default JS icon
    return (
        <svg xmlns="http://www.w3.org/2000/svg" className="w-10 h-10 text-sky-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M16 18l6-6-6-6"></path><path d="M8 6l-6 6 6 6"></path></svg>
    );
}

const PuzzleList: React.FC = () => {
    const { state, dispatch, selectCategory } = useAppContext();
    const { puzzles, selectedCategory, user } = state;
    const [difficultyFilter, setDifficultyFilter] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');

    const onStartPuzzle = (puzzle: Puzzle) => {
        dispatch({ type: 'START_PUZZLE', payload: puzzle });
    };

    const categories = Object.keys(puzzles);

    // Filter Logic (Applied only when inside a category)
    const categoryPuzzles = useMemo(() => {
        if (!selectedCategory) return [];
        const rawPuzzles = puzzles[selectedCategory] || [];
        return rawPuzzles.filter((puzzle) => {
            const difficultyMatch = difficultyFilter === 'All' || puzzle.difficulty === difficultyFilter;
            const searchMatch = puzzle.title.toLowerCase().includes(searchTerm.toLowerCase());
            return difficultyMatch && searchMatch;
        });
    }, [puzzles, selectedCategory, difficultyFilter, searchTerm]);

    // View: Category Selection (The "Hub")
    if (!selectedCategory) {
        return (
            <div className="container mx-auto px-4">
                <div className="text-center mb-12">
                     <h1 className="text-4xl font-bold text-slate-100 mb-4">Skill Areas</h1>
                     <p className="text-slate-400 max-w-2xl mx-auto">Select a topic to test your knowledge. Each category contains puzzles of varying difficulty to help you master the concepts.</p>
                </div>

                <motion.div 
                    className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
                    variants={containerVariants}
                    initial="hidden"
                    animate="visible"
                >
                    {categories.length > 0 ? categories.map((category) => {
                        const puzzleCount = puzzles[category]?.length || 0;
                        const solvedCount = puzzles[category]?.filter(p => user?.solvedPuzzleIds.includes(p.id)).length || 0;
                        const progress = puzzleCount > 0 ? (solvedCount / puzzleCount) * 100 : 0;

                        return (
                            <motion.div 
                                key={category} 
                                variants={itemVariants}
                                whileHover={{ scale: 1.03 }}
                                whileTap={{ scale: 0.98 }}
                                onClick={() => selectCategory(category)}
                                className="bg-slate-800/50 backdrop-blur-md rounded-2xl p-8 border border-slate-700 cursor-pointer hover:border-sky-500 hover:shadow-lg hover:shadow-sky-500/10 transition-all duration-300 group"
                            >
                                <div className="flex items-center justify-between mb-6">
                                    <div className="p-3 bg-slate-900 rounded-xl group-hover:bg-sky-500/20 transition-colors">
                                        {getCategoryIcon(category)}
                                    </div>
                                    <span className="bg-slate-700 text-slate-300 text-xs font-bold px-3 py-1 rounded-full">
                                        {puzzleCount} Puzzles
                                    </span>
                                </div>

                                <h2 className="text-2xl font-bold text-slate-100 mb-2 group-hover:text-sky-400 transition-colors">{category}</h2>
                                <p className="text-slate-400 text-sm mb-6">Master {category} concepts.</p>

                                <div className="w-full bg-slate-700 rounded-full h-1.5 mb-2">
                                    <div className="bg-sky-500 h-1.5 rounded-full transition-all duration-1000" style={{ width: `${progress}%` }}></div>
                                </div>
                                <p className="text-xs text-right text-slate-400">{solvedCount} / {puzzleCount} Solved</p>
                            </motion.div>
                        );
                    }) : (
                        <div className="col-span-full text-center text-slate-500 py-10">
                            No categories available. Please check back later.
                        </div>
                    )}
                </motion.div>
            </div>
        );
    }

    // View: Puzzle Grid (Specific to a Category)
    return (
        <div className="container mx-auto">
            <button 
                onClick={() => selectCategory(null)}
                className="flex items-center gap-2 text-sky-400 hover:text-sky-300 mb-6 transition-colors font-semibold group"
