                addToast(`Correct! +${puzzle.points} XP`, 'success');
                dispatch({ type: 'COMPLETE_PUZZLE', payload: { puzzleId: puzzle.id, points: puzzle.points }});
            }
        } else {
            // Keep the form active and just notify the user
            addToast('Not quite, try again!', 'error');
